// P1-T2 step 3 — «انقل ملاحظاتي إلى الإصدار الجديد»: copy, never move (BUILD_PLAN §3.4 step 3; ARCHITECTURE_DELTA §6.3;
// PRD AOS-3.13, 4.17, 4.20, Q35; Scenario 4 inside one vault). All PDFs are labelled TEST FIXTURES (generated by
// test/fixtures/versions/build.ts and test/fixtures/note-migration/build.ts).
//
// Scenario 4: ink on p.5 is copied to v2 p.5, a highlight on p.12 to v2 p.14, the p.30 note is listed for review with
// its candidate page; v1 rows stay byte-identical (hash); the preview writes nothing; a second run is a no-op; undo
// tombstones the copies only; counts before = moved + needs review + kept.
import { createHash } from 'node:crypto';
import { copyFileSync, mkdirSync, mkdtempSync, readdirSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import {
  newId,
  type PageMapEntry,
  type ReanchorCopyActionResponse,
  type ReanchorCopyPreview,
  type ReanchorCopyReport,
  type ReanchorCopyRunResponse,
  type SyncOp,
  type SyncOpResult,
} from '@medlevo/shared';
import { type Db, openDb } from '../../src/db/db';
import { migrate, MIGRATIONS_DIR } from '../../src/db/migrate';
import { newId as serverId } from '../../src/lib/ids';
import { planItem, quoteFoundIn, reanchorCopyId } from '../../src/modules/annotations/reanchorCopy';
import { insertedAndReordered, reorderedPageOf } from '../fixtures/note-migration/build';
import { scenario4V1, scenario4V2 } from '../fixtures/versions/build';
import type { AuthHeaders, TestApp } from '../helpers/app';
