// ───────────────────────────── the pure planner ─────────────────────────────
const entry = (e: Partial<PageMapEntry>): PageMapEntry => ({
  from_page_id: 'o1',
  from_page_index: 0,
  to_page_id: 'n1',
  to_page_index: 0,
  status: 'safe',
  method: 'identical',
  layout_safe: true,
  text_score: 1,
  image_distance: null,
  change: 'unchanged',
  decided_by: 'auto',
  ...e,
});

describe('planItem (pure): what may be copied without asking', () => {
  it('a safe page with the same layout takes every kind; a re-laid-out page takes only page anchors and found quotes', () => {
    const same = entry({});
    for (const k of ['ink', 'highlight', 'shape', 'text', 'sticky', 'image', 'link', 'bookmark', 'note']) expect(planItem(k, same, null)).toMatchObject({ action: 'copy', to_page_id: 'n1' });
    expect(planItem('text_highlight', same, { found: true, rects: null })).toMatchObject({ action: 'copy' });
    const relaid = entry({ layout_safe: false, change: 'edited' });
    expect(planItem('ink', relaid, null)).toMatchObject({ action: 'review', reason: 'layout_changed', suggested_page_id: 'n1' });
    expect(planItem('sticky', relaid, null)).toMatchObject({ action: 'review', reason: 'layout_changed' });
    expect(planItem('note', relaid, null)).toMatchObject({ action: 'copy' });
    expect(planItem('bookmark', relaid, null)).toMatchObject({ action: 'copy' });
    // a highlight on a re-laid-out page: copied only with rectangles re-derived from the new page's regions
    expect(planItem('text_highlight', relaid, { found: true, rects: null })).toMatchObject({ action: 'review', reason: 'layout_changed' });
    expect(planItem('text_highlight', relaid, { found: true, rects: [{ x: 0.1, y: 0.2, w: 0.3, h: 0.02 }] })).toMatchObject({ action: 'copy', rects: [{ x: 0.1, y: 0.2, w: 0.3, h: 0.02 }] });
    expect(planItem('text_highlight', same, { found: false, rects: null })).toMatchObject({ action: 'review', reason: 'quote_not_found' });
  });

  it('a page the owner confirmed counts as the same page (coordinates reused); uncertain, moved and removed pages are never guessed', () => {
    expect(planItem('ink', entry({ status: 'confirmed', layout_safe: false, decided_by: 'owner', method: 'owner' }), null)).toMatchObject({ action: 'copy' });
    expect(planItem('note', entry({ status: 'uncertain', change: 'changed' }), null)).toMatchObject({ action: 'review', reason: 'page_changed', suggested_page_id: 'n1' });
    expect(planItem('note', entry({ status: 'uncertain', change: 'moved' }), null)).toMatchObject({ action: 'review', reason: 'page_moved', suggested_page_id: 'n1' });
    expect(planItem('note', entry({ status: 'uncertain', change: 'unchanged' }), null)).toMatchObject({ action: 'review', reason: 'page_uncertain' });
    expect(planItem('ink', entry({ status: 'none', to_page_id: null, to_page_index: null, change: 'removed' }), null)).toMatchObject({ action: 'review', reason: 'page_removed', suggested_page_id: null });
    expect(planItem('ink', entry({ status: 'rejected', to_page_id: null, to_page_index: null, change: 'removed', decided_by: 'owner' }), null)).toMatchObject({ action: 'review', reason: 'page_removed' });
    expect(planItem('ink', undefined, null)).toMatchObject({ action: 'review', reason: 'page_removed' });
  });

  it('quotes are found again by their letters, not their spacing; an ambiguous repeat needs its context', () => {
    expect(quoteFoundIn('The rectus\nsheath encloses  the muscle.', { exact: 'rectus sheath encloses' })).toBe(true);
    expect(quoteFoundIn('الغمد المستقيم يحيط بالعضلة', { exact: 'المستقيم يحيط' })).toBe(true);
    expect(quoteFoundIn('fascia lata', { exact: 'rectus sheath' })).toBe(false);
    expect(quoteFoundIn('a b c', { exact: '   ' })).toBe(false);
    // twice on the page: the prefix decides
    expect(quoteFoundIn('first: inguinal canal. second: inguinal canal.', { exact: 'inguinal canal', prefix: 'second: ' })).toBe(true);
    expect(quoteFoundIn('first: inguinal canal. second: inguinal canal.', { exact: 'inguinal canal', prefix: 'third: ' })).toBe(false);
  });

  it('copy ids are deterministic per original and target version', () => {
    expect(reanchorCopyId('A', 'V2')).toBe(reanchorCopyId('A', 'V2'));
    expect(reanchorCopyId('A', 'V2')).not.toBe(reanchorCopyId('A', 'V3'));
    expect(reanchorCopyId('A', 'V2')).toMatch(/^rc_[0-9a-f]{26}$/);
  });
});

// ───────────────────────────── one lecture with two versions ─────────────────────────────
interface Lecture {
  sourceId: string;
  v1: string;
  v2: string;
  v1Pages: string[];
  v2Pages: string[];
}

async function addVersion(t: TestApp, sourceId: string, data: Buffer, fileName: string): Promise<string> {
  const { ctx } = t;
  const now = ctx.clock.now();
  const stored = await ctx.files.put(data, { mime: 'application/pdf', originalName: fileName });
  const id = serverId(now);
  const no = ctx.db.get<{ n: number }>('SELECT MAX(version_no) AS n FROM source_version WHERE source_id = ?', [sourceId])!.n + 1;
  ctx.db.run(
    `INSERT INTO source_version (id, source_id, version_no, kind, file_id, content_hash, mime, file_name, format, pagination, processing_status, created_at)
     VALUES (?, ?, ?, 'replacement', ?, ?, 'application/pdf', ?, 'pdf', 'pages', 'pending', ?)`,
    [id, sourceId, no, stored.id, createHash('sha256').update(data).digest('hex'), fileName, now],
  );
  ctx.db.run('UPDATE source SET current_version_id = ? WHERE id = ?', [id, sourceId]);
  return id;
}

async function lectureWith(t: TestApp, v2Data: Buffer, title: string): Promise<Lecture> {
  const a = await addSource(t, 'x.pdf', 'pdf', { data: scenario4V1(), fileName: 'Abdomen Lecture 5.pdf', title });
  await processVersion(t, a.versionId);
  const v2 = await addVersion(t, a.sourceId, v2Data, 'Abdomen lec5 final (1).pdf');
  await processVersion(t, v2);
  await t.ctx.jobs.drain();
  const pages = (v: string) => t.ctx.db.all<{ id: string }>('SELECT id FROM source_page WHERE version_id = ? ORDER BY page_index', [v]).map((r) => r.id);
  return { sourceId: a.sourceId, v1: a.versionId, v2, v1Pages: pages(a.versionId), v2Pages: pages(v2) };
}

let opN = 0;
const op = (o: Partial<SyncOp> & Pick<SyncOp, 'entity_type' | 'entity_id'>): SyncOp => ({ op_id: `RCOP${Date.now()}${String(++opN).padStart(5, '0')}`, device_id: 'DEVICE_A', op: 'upsert', payload: {}, client_ts: Date.now(), ...o });
const anchorOf = (L: Lecture, page: number, v: 'v1' | 'v2' = 'v1') => ({
  type: 'page' as const,
  source_id: L.sourceId,
  version_id: v === 'v1' ? L.v1 : L.v2,
  page_id: (v === 'v1' ? L.v1Pages : L.v2Pages)[page - 1]!,
  page_index: page - 1,
  space: 'page_norm' as const,
});
const ink = (x = 0.2, y = 0.3) => ({
  v: 1,
  points: [
    [x, y, 0, 0.5],
    [x + 0.1, y + 0.02, 16, 0.6],
  ],
  style: { tool: 'pen', color: 'ink-blue', width: 0.0025 },
  bbox: { x, y, w: 0.1, h: 0.02 },
  pressure_available: true,
  tilt_available: false,
});
const rt = (text: string) => ({ v: 1, paragraphs: [{ dir: 'rtl', runs: [{ t: text }] }] });

/** The first sentence of a page's first body region (the text a highlight on it would quote) and its box. */
function quoteOn(t: TestApp, pageId: string): { exact: string; box: { x: number; y: number; w: number; h: number } } {
  const r = t.ctx.db.get<{ text: string; bbox_json: string }>(
    `SELECT text, bbox_json FROM source_region WHERE page_id = ? AND text IS NOT NULL AND kind NOT IN ('heading','header','footer') AND bbox_json IS NOT NULL ORDER BY reading_order LIMIT 1`,
    [pageId],
  )!;
  return { exact: r.text.replace(/\s+/g, ' ').trim().slice(0, 48).trim(), box: JSON.parse(r.bbox_json) };
}

interface Seeded {
  ink5: string;
  hl12: string;
  note30: string;
  note36?: string;
}

async function seed(t: TestApp, h: AuthHeaders, L: Lecture, opts: { note36?: boolean } = {}): Promise<Seeded> {
  const ids: Seeded = { ink5: newId(), hl12: newId(), note30: newId(), ...(opts.note36 ? { note36: newId() } : {}) };
  const q = quoteOn(t, L.v1Pages[11]!);
  const ops: SyncOp[] = [
    op({ entity_type: 'annotation', entity_id: ids.ink5, op: 'append', payload: { kind: 'ink', tool: 'pen', anchor: anchorOf(L, 5), data: ink(), layer: 'ink', z: 0, locked: false } }),
    op({
      entity_type: 'annotation',
      entity_id: ids.hl12,
      op: 'append',
      payload: { kind: 'text_highlight', tool: 'highlight', anchor: anchorOf(L, 12), data: { v: 1, style: 'highlight', color: 'marker-yellow', rects: [{ ...q.box, h: Math.min(q.box.h, 0.02) }], quote: { exact: q.exact } }, layer: 'highlight', z: 0, locked: false },
    }),
    op({ entity_type: 'note', entity_id: ids.note30, payload: { node_id: null, title: null, body: rt('ملاحظتي على الصفحة 30'), anchor: anchorOf(L, 30), origin: 'owner' } }),
  ];
  if (ids.note36) ops.push(op({ entity_type: 'note', entity_id: ids.note36, payload: { node_id: null, title: null, body: rt('ملاحظتي على الصفحة 36'), anchor: anchorOf(L, 36), origin: 'owner' } }));
  const res = await t.app.inject({ method: 'POST', url: '/api/sync/push', headers: h, payload: { ops } });
  expect(res.statusCode, res.body).toBe(200);
  for (const r of res.json().results as SyncOpResult[]) expect(r.result, JSON.stringify(r)).toBe('applied');
  return ids;
}

/** sha256 over every stored row of the earlier version's items (the guarantee: the originals never change) */
function v1Hash(db: Db, ids: string[]): string {
  const ph = ids.map(() => '?').join(',');
  const rows = [
    ...db.all(`SELECT * FROM annotation WHERE id IN (${ph}) ORDER BY id`, ids),
    ...db.all(`SELECT * FROM note WHERE id IN (${ph}) ORDER BY id`, ids),
    ...db.all(`SELECT * FROM annotation_target WHERE annotation_id IN (${ph}) ORDER BY annotation_id`, ids),
  ];
  return createHash('sha256').update(JSON.stringify(rows)).digest('hex');
}

const counts = (db: Db) => ({
  annotations: db.get<{ n: number }>('SELECT COUNT(*) AS n FROM annotation')!.n,
  notes: db.get<{ n: number }>('SELECT COUNT(*) AS n FROM note')!.n,
  runs: db.get<{ n: number }>('SELECT COUNT(*) AS n FROM reanchor_copy_run')!.n,
});

describe('Scenario 4 (TEST FIXTURE): 2 pages inserted after p.10, p.30 rewritten', () => {
  let t: TestApp;
  let h: AuthHeaders;
  let L: Lecture;
  let ids: Seeded;
  let hash: string;
  const preview = async (q = ''): Promise<ReanchorCopyPreview> => {
    const res = await t.app.inject({ method: 'GET', url: `/api/annotations/reanchor-copy?source_id=${L.sourceId}${q}`, headers: h });
    expect(res.statusCode, res.body).toBe(200);
    return res.json() as ReanchorCopyPreview;
  };
  const run = async (body: Record<string, unknown> = {}, status = 200) => {
    const res = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy', headers: h, payload: { source_id: L.sourceId, from_version_id: L.v1, to_version_id: L.v2, ...body } });
    expect(res.statusCode, res.body).toBe(status);
    return res.json() as ReanchorCopyRunResponse & { error?: { code: string; message: string } };
  };
  const undo = async (runId: string, status = 200) => {
    const res = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy/undo', headers: h, payload: { run_id: runId } });
    expect(res.statusCode, res.body).toBe(status);
    return res.json() as { report: ReanchorCopyReport };
  };

  beforeAll(async () => {
    t = await createProcessingApp();
    h = await t.login();
    L = await lectureWith(t, scenario4V2(), 'TEST FIXTURE Abdomen Lecture 5');
    ids = await seed(t, h, L);
    hash = v1Hash(t.ctx.db, Object.values(ids));
  }, 120_000);
  afterAll(async () => t?.close());

  it('the preview says what the tap will do and writes nothing: 2 to copy, 1 for review, 0 kept', async () => {
    const before = counts(t.ctx.db);
    const pv = await preview();
    expect(pv).toMatchObject({ state: 'ready', from_version: { id: L.v1, version_no: 1 }, to_version: { id: L.v2, version_no: 2 }, total: 3, copy: 2, already_moved: 0, needs_review: 1, kept: 0 });
    expect(pv.total).toBe(pv.copy + pv.already_moved + pv.needs_review + pv.kept);
    expect(pv.summary_ar).toBe('سيُنقل 2 · يحتاج مراجعة 1 · يبقى على الإصدار 1: 0');
    // p.5 → v2 p.5, p.12 → v2 p.14 (shifted by the two inserted pages)
    expect(pv.will_copy.map((w) => [w.from_page_index + 1, w.page.page_index + 1, w.items])).toEqual([
      [5, 5, 1],
      [12, 14, 1],
    ]);
    expect(pv.will_copy.map((w) => w.from.page_id)).toEqual([L.v1Pages[4], L.v1Pages[11]]);
    expect(pv.by_kind).toEqual({ ink: 1, text_highlight: 1 });
    // the p.30 note: listed, with its old place and the page map's candidate (v2 p.32), never copied by itself
    expect(pv.review).toHaveLength(1);
    expect(pv.review[0]).toMatchObject({ kind: 'note', id: ids.note30, item_kind: 'note', reason: 'page_changed', from: { page_index: 29 }, suggested: { page_index: 31, page_id: L.v2Pages[31] } });
    expect(pv.review[0]!.preview).toContain('ملاحظتي على الصفحة 30');
    expect(pv.review[0]!.from.thumbnail).toBe(true);
    expect(pv.earlier).toEqual([{ version: { id: L.v1, version_no: 1 }, items: 3, pending: 3 }]);
    expect(pv.last_run).toBeNull();
    // the defaults are the same pair (newest version; the newest earlier version with personal items)
    expect(await preview(`&from_version_id=${L.v1}&to_version_id=${L.v2}`)).toEqual(pv);
    expect(counts(t.ctx.db)).toEqual(before);
    expect(v1Hash(t.ctx.db, Object.values(ids))).toBe(hash);
  });

  it('the tap copies (deterministic ids, previous anchor kept, same layer); the originals stay byte-identical', async () => {
    const pv = await preview();
    const { report } = await run({ map_computed_at: pv.map_computed_at });
    expect(report).toMatchObject({ kind: 'run', total: 3, copied: 2, already_moved: 0, needs_review: 1, kept: 0, pages: 2, undone_at: null });
    expect(report.total).toBe(report.copied + report.already_moved + report.needs_review + report.kept);
    expect(report.summary_ar).toBe('نُقل عنصران إلى صفحتين؛ عنصر واحد يحتاج مراجعتك؛ لا شيء بقي على الإصدار السابق');
    expect(report.id).toMatch(/.+/);

    const ink5 = t.ctx.db.get<Record<string, unknown>>('SELECT * FROM annotation WHERE id = ?', [reanchorCopyId(ids.ink5, L.v2)])!;
    const orig = t.ctx.db.get<Record<string, unknown>>('SELECT * FROM annotation WHERE id = ?', [ids.ink5])!;
    expect(ink5).toMatchObject({ origin: 'reanchor_copy', migrated_from_id: ids.ink5, anchor_status: 'reanchored', layer_id: orig.layer_id, deleted_at: null, rev: 1, kind: 'ink' });
    expect(JSON.parse(ink5.anchor_json as string)).toEqual(anchorOf(L, 5, 'v2'));
    expect(JSON.parse(ink5.previous_anchor_json as string)).toEqual(anchorOf(L, 5));
    expect(ink5.data_json).toBe(orig.data_json); // same normalised coordinates (layout_safe)
    expect(t.ctx.db.get('SELECT target_type, target_id FROM annotation_target WHERE annotation_id = ?', [ink5.id])).toEqual({ target_type: 'source_page', target_id: L.v2Pages[4] });
    const hl = t.ctx.db.get<{ anchor_json: string; data_json: string }>('SELECT anchor_json, data_json FROM annotation WHERE id = ?', [reanchorCopyId(ids.hl12, L.v2)])!;
    expect(JSON.parse(hl.anchor_json)).toEqual(anchorOf(L, 14, 'v2'));
    expect(hl.data_json).toBe(t.ctx.db.get<{ data_json: string }>('SELECT data_json FROM annotation WHERE id = ?', [ids.hl12])!.data_json);
    // the note waits for review: no copy
    expect(t.ctx.db.get('SELECT 1 AS x FROM note WHERE id = ?', [reanchorCopyId(ids.note30, L.v2)])).toBeUndefined();
    // the originals: unchanged, still on v1
    expect(v1Hash(t.ctx.db, Object.values(ids))).toBe(hash);

    // every device learns of the copies through the sync feed
    const pull = await t.app.inject({ method: 'GET', url: '/api/sync/pull?since=0&limit=1000', headers: h });
    expect(pull.statusCode, pull.body).toBe(200);
    const changed = (pull.json().changes as Array<{ entity_type: string; entity_id: string }>).map((c) => `${c.entity_type}:${c.entity_id}`);
    expect(changed).toEqual(expect.arrayContaining([`annotation:${reanchorCopyId(ids.ink5, L.v2)}`, `annotation:${reanchorCopyId(ids.hl12, L.v2)}`]));

    // the reader of v2 gets them; v1 still shows the originals
    const v2read = await t.app.inject({ method: 'GET', url: `/api/annotations/source/${L.sourceId}?version_id=${L.v2}`, headers: h });
    expect((v2read.json().annotations as Array<{ id: string; migrated_from_id?: string; origin?: string }>).map((a) => [a.migrated_from_id, a.origin]).sort()).toEqual(
      [
        [ids.hl12, 'reanchor_copy'],
        [ids.ink5, 'reanchor_copy'],
      ].sort(),
    );
  });

  it('a second run is a no-op (nothing copied twice, nothing recorded)', async () => {
    const before = counts(t.ctx.db);
    const { report } = await run();
    expect(report).toMatchObject({ id: null, copied: 0, already_moved: 2, needs_review: 1, kept: 0, total: 3 });
    expect(counts(t.ctx.db)).toEqual(before);
    const pv = await preview();
    expect(pv).toMatchObject({ copy: 0, already_moved: 2, needs_review: 1, kept: 0, total: 3 });
    expect(pv.summary_ar).toBe('سيُنقل 0 · يحتاج مراجعة 1 · يبقى على الإصدار 1: 0 · نُقل سابقًا: 2');
    expect(pv.last_run).toMatchObject({ kind: 'run', copied: 2, undone_at: null });
  });

  it('a map that changed since the preview refuses the tap (409) and copies nothing', async () => {
    const before = counts(t.ctx.db);
    const res = await run({ map_computed_at: 1 }, 409);
    expect(res.error?.message).toMatch(/تغيّرت مطابقة الصفحات/);
    expect(counts(t.ctx.db)).toEqual(before);
  });

  it('review: the p.30 note is copied by the owner to the page they pick (Round 7 re-anchoring route, as a COPY)', async () => {
    const pv = await preview();
    const item = pv.review[0]!;
    const res = await t.app.inject({
      method: 'POST',
      url: '/api/annotations/reanchor',
      headers: h,
      payload: { action: 'copy', items: [{ kind: 'note', id: item.id, rev: item.rev }], to_version_id: L.v2, target: { type: 'page', version_id: L.v2, page_id: L.v2Pages[31] } },
    });
    expect(res.statusCode, res.body).toBe(200);
    const body = res.json() as ReanchorCopyActionResponse;
    expect(body.notes.map((n) => n.id)).toEqual([reanchorCopyId(ids.note30, L.v2)]);
    expect(body.notes[0]).toMatchObject({ migrated_from_id: ids.note30, anchor: anchorOf(L, 32, 'v2'), previous_anchor: anchorOf(L, 30) });
    expect(body.report).toMatchObject({ kind: 'manual', copied: 1 });
    expect(body.summary_ar).toMatch(/نُسخت الملاحظة/);
    expect(v1Hash(t.ctx.db, Object.values(ids))).toBe(hash);
    const after = await preview();
    expect(after).toMatchObject({ copy: 0, already_moved: 3, needs_review: 0, kept: 0, total: 3, review: [] });
    // the same copy twice → refused (stale list); nothing duplicated
    const again = await t.app.inject({
      method: 'POST',
      url: '/api/annotations/reanchor',
      headers: h,
      payload: { action: 'copy', items: [{ kind: 'note', id: item.id, rev: item.rev }], to_version_id: L.v2, target: { type: 'page', version_id: L.v2, page_id: L.v2Pages[31] } },
    });
    expect(again.statusCode, again.body).toBe(409);
    // the review copy is undone on its own
    const u = await undo(body.report!.id!);
    expect(u.report).toMatchObject({ kind: 'manual', undo: { tombstoned: 1, kept_edited: 0 } });
    expect(t.ctx.db.get<{ deleted_at: number | null }>('SELECT deleted_at FROM note WHERE id = ?', [reanchorCopyId(ids.note30, L.v2)])!.deleted_at).not.toBeNull();
    expect((await preview()).needs_review).toBe(1);
  });

  it('«اتركها على الإصدار السابق»: the item is counted kept (nothing written to it); «review again» lists it again', async () => {
    const pv = await preview();
    const item = pv.review[0]!;
    const keep = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor', headers: h, payload: { action: 'keep_on_previous', items: [{ kind: 'note', id: item.id, rev: item.rev }], to_version_id: L.v2 } });
    expect(keep.statusCode, keep.body).toBe(200);
    expect((keep.json() as ReanchorCopyActionResponse).summary_ar).toMatch(/تبقى على الإصدار 1/);
    const kept = await preview();
    expect(kept).toMatchObject({ copy: 0, already_moved: 2, needs_review: 0, kept: 1, total: 3 });
    expect(kept.kept_by_reason).toEqual([{ reason: 'owner_choice', reason_ar: expect.any(String), items: 1 }]);
    expect(kept.kept_items).toEqual([expect.objectContaining({ kind: 'note', id: item.id, item_kind: 'note', from: expect.objectContaining({ page_index: 29 }) })]);
    expect(v1Hash(t.ctx.db, Object.values(ids))).toBe(hash);
    const again = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor', headers: h, payload: { action: 'review_again', items: [{ kind: 'note', id: item.id, rev: item.rev }], to_version_id: L.v2 } });
    expect(again.statusCode, again.body).toBe(200);
    expect((await preview()).needs_review).toBe(1);
  });

  it('undo tombstones the copies only (an edited copy is kept); a new tap revives the same ids', async () => {
    const pv = await preview();
    const runId = pv.last_run!.id!;
    // the owner changed the highlight copy after the copy: undo keeps it
    const hlCopy = reanchorCopyId(ids.hl12, L.v2);
    const row = t.ctx.db.get<{ rev: number }>('SELECT rev FROM annotation WHERE id = ?', [hlCopy])!;
    const dto = (await t.app.inject({ method: 'GET', url: `/api/annotations/source/${L.sourceId}?version_id=${L.v2}`, headers: h })).json().annotations.find((a: { id: string }) => a.id === hlCopy);
    const edit = await t.app.inject({
      method: 'POST',
      url: '/api/sync/push',
      headers: h,
      payload: { ops: [op({ entity_type: 'annotation', entity_id: hlCopy, base_rev: row.rev, payload: { ...dto, data: { ...dto.data, style: 'underline', color: 'ink-accent' } } })] },
    });
    expect(edit.statusCode, edit.body).toBe(200);
    expect((edit.json().results as SyncOpResult[])[0]!.result).toBe('applied');

    const { report } = await undo(runId);
    expect(report).toMatchObject({ undo: { tombstoned: 1, kept_edited: 1 } });
    expect(report.undone_at).not.toBeNull();
    const inkCopy = t.ctx.db.get<{ deleted_at: number | null }>('SELECT deleted_at FROM annotation WHERE id = ?', [reanchorCopyId(ids.ink5, L.v2)])!;
    expect(inkCopy.deleted_at).not.toBeNull();
    expect(t.ctx.db.get<{ deleted_at: number | null }>('SELECT deleted_at FROM annotation WHERE id = ?', [hlCopy])!.deleted_at).toBeNull();
    // the originals: never touched by the undo either
    expect(v1Hash(t.ctx.db, Object.values(ids))).toBe(hash);
    // a second undo is a no-op
    expect((await undo(runId)).report.undo).toEqual({ tombstoned: 1, kept_edited: 1 });

    // the ink is pending again; a new tap revives the same deterministic id (no duplicate row)
    const pv2 = await preview();
    expect(pv2).toMatchObject({ copy: 1, already_moved: 1, needs_review: 1, kept: 0, total: 3 });
    const before = counts(t.ctx.db);
    const again = await run();
    expect(again.report).toMatchObject({ copied: 1, already_moved: 1 });
    expect(counts(t.ctx.db).annotations).toBe(before.annotations);
    expect(t.ctx.db.get<{ deleted_at: number | null; rev: number }>('SELECT deleted_at, rev FROM annotation WHERE id = ?', [reanchorCopyId(ids.ink5, L.v2)])).toMatchObject({ deleted_at: null, rev: 3 });
  });

  it('an item the owner erased on the new version is never revived by a later tap', async () => {
    const copy = reanchorCopyId(ids.ink5, L.v2);
    const row = t.ctx.db.get<{ rev: number }>('SELECT rev FROM annotation WHERE id = ?', [copy])!;
    const del = await t.app.inject({ method: 'POST', url: '/api/sync/push', headers: h, payload: { ops: [op({ entity_type: 'annotation', entity_id: copy, op: 'delete', base_rev: row.rev })] } });
    expect((del.json().results as SyncOpResult[])[0]!.result).toBe('applied');
    const { report } = await run();
    expect(report).toMatchObject({ copied: 0, already_moved: 2 });
    expect(t.ctx.db.get<{ deleted_at: number | null }>('SELECT deleted_at FROM annotation WHERE id = ?', [copy])!.deleted_at).not.toBeNull();
  });

  it('refuses nonsense: another lecture, the same version, a backwards copy, an unknown version', async () => {
    const bad = async (body: Record<string, unknown>, status: number) => {
      const res = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy', headers: h, payload: { source_id: L.sourceId, from_version_id: L.v1, to_version_id: L.v2, ...body } });
      expect(res.statusCode, res.body).toBe(status);
    };
    await bad({ to_version_id: L.v1 }, 400);
    await bad({ from_version_id: L.v2, to_version_id: L.v1 }, 400);
    await bad({ to_version_id: 'NOPE' }, 404);
    await bad({ source_id: 'OTHER' }, 404);
    const res = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy/undo', headers: h, payload: { run_id: 'NOPE' } });
    expect(res.statusCode).toBe(404);
  });
});

describe('pages inserted AND reordered (TEST FIXTURE): moved pages are suggested, never guessed', () => {
  let t: TestApp;
  let h: AuthHeaders;
  let L: Lecture;
  let ids: Seeded;
  beforeAll(async () => {
    t = await createProcessingApp();
    h = await t.login();
    L = await lectureWith(t, insertedAndReordered(), 'TEST FIXTURE Abdomen Lecture 5 (reordered)');
    ids = await seed(t, h, L, { note36: true });
  }, 120_000);
  afterAll(async () => t?.close());

  it('p.5 → p.5 and p.12 → p.14 are copied; p.30 (changed) and p.36 (moved to p.27) are listed with their candidates', async () => {
    const res = await t.app.inject({ method: 'GET', url: `/api/annotations/reanchor-copy?source_id=${L.sourceId}`, headers: h });
    const pv = res.json() as ReanchorCopyPreview;
    expect(pv).toMatchObject({ state: 'ready', total: 4, copy: 2, needs_review: 2, kept: 0 });
    expect(pv.will_copy.map((w) => [w.from_page_index + 1, w.page.page_index + 1])).toEqual([
      [5, reorderedPageOf(5)],
      [12, reorderedPageOf(12)],
    ]);
    const byId = new Map(pv.review.map((r) => [r.id, r]));
    expect(byId.get(ids.note30)).toMatchObject({ reason: 'page_changed', suggested: { page_index: reorderedPageOf(30) - 1 } });
    expect(byId.get(ids.note36!)).toMatchObject({ reason: 'page_moved', suggested: { page_index: reorderedPageOf(36) - 1 } });

    const runRes = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy', headers: h, payload: { source_id: L.sourceId, from_version_id: L.v1, to_version_id: L.v2 } });
    expect((runRes.json() as ReanchorCopyRunResponse).report).toMatchObject({ copied: 2, needs_review: 2, total: 4 });
    // the moved page follows only on the owner's word: one tap on the suggestion copies it there
    const moved = byId.get(ids.note36!)!;
    const copy = await t.app.inject({
      method: 'POST',
      url: '/api/annotations/reanchor',
      headers: h,
      payload: { action: 'copy', items: [{ kind: 'note', id: moved.id, rev: moved.rev }], to_version_id: L.v2, target: { type: 'page', version_id: L.v2, page_id: moved.suggested!.page_id } },
    });
    expect(copy.statusCode, copy.body).toBe(200);
    expect((copy.json() as ReanchorCopyActionResponse).notes[0]!.anchor).toEqual(anchorOf(L, reorderedPageOf(36), 'v2'));
  });

  it('an owner confirmation on the compare screen turns a moved page into a copy target for ink as well', async () => {
    // ink on v1 p.36 (moved): listed for review until the owner confirms the pair in the page map
    const inkId = newId();
    await t.app.inject({ method: 'POST', url: '/api/sync/push', headers: h, payload: { ops: [op({ entity_type: 'annotation', entity_id: inkId, op: 'append', payload: { kind: 'ink', tool: 'pen', anchor: anchorOf(L, 36), data: ink(0.5, 0.5), layer: 'ink', z: 0, locked: false } })] } });
    let pv = (await t.app.inject({ method: 'GET', url: `/api/annotations/reanchor-copy?source_id=${L.sourceId}`, headers: h })).json() as ReanchorCopyPreview;
    expect(pv.review.find((r) => r.id === inkId)).toMatchObject({ reason: 'page_moved' });
    const decide = await t.app.inject({ method: 'POST', url: '/api/versions/maps/decide', headers: h, payload: { from_version_id: L.v1, to_version_id: L.v2, from_page_id: L.v1Pages[35], action: 'confirm' } });
    expect(decide.statusCode, decide.body).toBe(200);
    pv = (await t.app.inject({ method: 'GET', url: `/api/annotations/reanchor-copy?source_id=${L.sourceId}`, headers: h })).json() as ReanchorCopyPreview;
    expect(pv.review.find((r) => r.id === inkId)).toBeUndefined();
    expect(pv.will_copy.map((w) => w.page.page_index + 1)).toContain(reorderedPageOf(36));
  });
});

describe('layers, purge and the migration on an existing database', () => {
  let t: TestApp;
  let h: AuthHeaders;
  let L: Lecture;
  beforeAll(async () => {
    t = await createProcessingApp();
    h = await t.login();
    L = await lectureWith(t, scenario4V2(), 'TEST FIXTURE Abdomen Lecture 5 (layers)');
  }, 120_000);
  afterAll(async () => t?.close());

  it('a copy keeps its layer; an item of a read-only (followed) layer stays on its version, counted kept', async () => {
    const doc = `source:${L.sourceId}`;
    const now = t.ctx.clock.now();
    t.ctx.db.run(
      `INSERT INTO annotation_layer (id, document_key, kind, title, writable, frozen, visible, locked, sort_order, rev, created_at, updated_at) VALUES ('LY_ANS', ?, 'answers', 'إجاباتي', 1, 0, 1, 0, 1, 1, ?, ?)`,
      [doc, now, now],
    );
    t.ctx.db.run(
      `INSERT INTO annotation_layer (id, document_key, kind, title, writable, frozen, origin_json, visible, locked, sort_order, rev, created_at, updated_at) VALUES ('LY_FOL', ?, 'followed', 'شرح حسن', 0, 0, '{"author_user_id":"u_hasan","author_display":"حسن"}', 1, 0, 2, 1, ?, ?)`,
      [doc, now, now],
    );
    const own = newId();
    await t.app.inject({ method: 'POST', url: '/api/sync/push', headers: h, payload: { ops: [op({ entity_type: 'annotation', entity_id: own, op: 'append', payload: { kind: 'ink', tool: 'pen', anchor: anchorOf(L, 5), data: ink(), layer: 'ink', z: 0, locked: false, layer_id: 'LY_ANS' } })] } });
    // a followed author's stroke (written by the follow feed, not by a client)
    t.ctx.db.run(
      `INSERT INTO annotation (id, kind, tool, anchor_json, data_json, layer, z, locked, anchor_status, rev, created_at, updated_at, layer_id, author_user_id, origin) VALUES ('FOLLOWED1', 'ink', 'pen', ?, ?, 'ink', 0, 0, 'ok', 1, ?, ?, 'LY_FOL', 'u_hasan', 'follow_copy')`,
      [JSON.stringify(anchorOf(L, 6)), JSON.stringify(ink()), now, now],
    );
    t.ctx.db.run(`INSERT INTO annotation_target (annotation_id, target_type, target_id) VALUES ('FOLLOWED1', 'source_page', ?)`, [L.v1Pages[5]]);
    const pv = (await t.app.inject({ method: 'GET', url: `/api/annotations/reanchor-copy?source_id=${L.sourceId}`, headers: h })).json() as ReanchorCopyPreview;
    expect(pv).toMatchObject({ total: 2, copy: 1, kept: 1, needs_review: 0 });
    expect(pv.kept_by_reason).toEqual([{ reason: 'read_only_layer', reason_ar: expect.any(String), items: 1 }]);
    const res = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy', headers: h, payload: { source_id: L.sourceId, from_version_id: L.v1, to_version_id: L.v2 } });
    expect((res.json() as ReanchorCopyRunResponse).report).toMatchObject({ copied: 1, kept: 1, total: 2 });
    expect(t.ctx.db.get('SELECT layer_id FROM annotation WHERE id = ?', [reanchorCopyId(own, L.v2)])).toEqual({ layer_id: 'LY_ANS' });
    expect(t.ctx.db.get('SELECT 1 AS x FROM annotation WHERE id = ?', [reanchorCopyId('FOLLOWED1', L.v2)])).toBeUndefined();
    // the follower cannot copy a followed author's item from the review route either
    const refused = await t.app.inject({
      method: 'POST',
      url: '/api/annotations/reanchor',
      headers: h,
      payload: { action: 'copy', items: [{ kind: 'annotation', id: 'FOLLOWED1', rev: 1 }], to_version_id: L.v2, target: { type: 'page', version_id: L.v2, page_id: L.v2Pages[5] } },
    });
    expect(refused.statusCode, refused.body).toBe(409);
  });

  it('a newer version still being processed: the preview says so (counts kept honest) and the tap is refused, nothing written', async () => {
    const now = t.ctx.clock.now();
    const v3 = serverId(now);
    t.ctx.db.run(
      `INSERT INTO source_version (id, source_id, version_no, kind, content_hash, mime, file_name, format, pagination, processing_status, created_at) VALUES (?, ?, 3, 'replacement', 'h3', 'application/pdf', 'v3.pdf', 'pdf', 'pages', 'pending', ?)`,
      [v3, L.sourceId, now],
    );
    try {
      const pv = (await t.app.inject({ method: 'GET', url: `/api/annotations/reanchor-copy?source_id=${L.sourceId}`, headers: h })).json() as ReanchorCopyPreview;
      expect(pv).toMatchObject({ state: 'pending', to_version: { id: v3, version_no: 3 }, copy: 0, needs_review: 0, will_copy: [], review: [] });
      expect(pv.reason_ar).toMatch(/يُعالَج الإصدار 3/);
      const before = counts(t.ctx.db);
      const res = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy', headers: h, payload: { source_id: L.sourceId, from_version_id: L.v2, to_version_id: v3 } });
      expect(res.statusCode, res.body).toBe(409);
      expect(counts(t.ctx.db)).toEqual(before);
    } finally {
      t.ctx.db.run('DELETE FROM source_version WHERE id = ?', [v3]);
    }
  });

  it('the full JSON export carries the note-migration records (and the copies as ordinary annotations)', async () => {
    const res = await t.app.inject({ method: 'GET', url: '/api/data/export/all', headers: h });
    expect(res.statusCode, res.body.slice(0, 300)).toBe(200);
    const out = JSON.parse(res.body) as { data: Record<string, Array<Record<string, unknown>>> };
    expect(out.data.reanchor_copy_run!.length).toBeGreaterThan(0);
    expect(out.data.reanchor_copy_item!.map((r) => r.copy_id)).toContain(t.ctx.db.get<{ id: string }>(`SELECT id FROM annotation WHERE origin = 'reanchor_copy' LIMIT 1`)!.id);
    expect(out.data.reanchor_copy_decision).toEqual([]);
    expect(out.data.annotation!.some((a) => a.origin === 'reanchor_copy')).toBe(true);
  });

  it('purging the lecture removes the run records, the copies and the decisions with it', async () => {
    expect(t.ctx.db.get<{ n: number }>('SELECT COUNT(*) AS n FROM reanchor_copy_run')!.n).toBeGreaterThan(0);
    expect((await t.app.inject({ method: 'POST', url: `/api/sources/${L.sourceId}/trash`, headers: h })).statusCode).toBe(200);
    const impact = (await t.app.inject({ method: 'GET', url: `/api/sources/${L.sourceId}/impact?mode=purge`, headers: h })).json() as { confirm_token: string; lines_ar: string[] };
    expect(impact.lines_ar.join('\n')).toMatch(/سجل نقل الملاحظات إلى إصدار أحدث/);
    const purge = await t.app.inject({ method: 'DELETE', url: `/api/sources/${L.sourceId}?confirm_token=${encodeURIComponent(impact.confirm_token)}`, headers: h });
    expect(purge.statusCode, purge.body).toBe(200);
    expect(t.ctx.db.get<{ n: number }>('SELECT COUNT(*) AS n FROM reanchor_copy_run')!.n).toBe(0);
    expect(t.ctx.db.get<{ n: number }>('SELECT COUNT(*) AS n FROM reanchor_copy_item')!.n).toBe(0);
    expect(t.ctx.db.get<{ n: number }>('SELECT COUNT(*) AS n FROM reanchor_copy_decision')!.n).toBe(0);
  });

  it('0273 is additive on the owner’s existing database (applied after every newer file; nothing else changes)', () => {
    const dir = mkdtempSync(join(tmpdir(), 'medlevo-rc-mig-'));
    try {
      const prev = join(dir, 'previous');
      mkdirSync(prev);
      for (const f of readdirSync(MIGRATIONS_DIR)) if (f.endsWith('.sql') && f !== '0273_reanchor_copy.sql') copyFileSync(join(MIGRATIONS_DIR, f), join(prev, f));
      const db = openDb(join(dir, 'vault.db'));
      migrate(db, { dir: prev });
      const schemaBefore = db.all<{ name: string; sql: string }>("SELECT name, sql FROM sqlite_master WHERE type IN ('table','index') AND sql IS NOT NULL ORDER BY name");
      migrate(db);
      const schemaAfter = db.all<{ name: string; sql: string }>("SELECT name, sql FROM sqlite_master WHERE type IN ('table','index') AND sql IS NOT NULL ORDER BY name");
      expect(schemaAfter.filter((r) => !r.name.includes('reanchor_copy'))).toEqual(schemaBefore);
      expect(schemaAfter.filter((r) => r.name.includes('reanchor_copy')).map((r) => r.name)).toEqual([
        'idx_reanchor_copy_item_from',
        'idx_reanchor_copy_item_run',
        'idx_reanchor_copy_run_pair',
        'reanchor_copy_decision',
        'reanchor_copy_item',
        'reanchor_copy_run',
      ]);
      db.close();
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

describe('performance: the 5 000-stroke page (measured, not a device number)', () => {
  let t: TestApp;
  let h: AuthHeaders;
  let L: Lecture;
  beforeAll(async () => {
    t = await createProcessingApp();
    h = await t.login();
    L = await lectureWith(t, scenario4V2(), 'TEST FIXTURE Abdomen Lecture 5 (dense)');
  }, 120_000);
  afterAll(async () => t?.close());

  it('preview and tap over 5 000 strokes on v1 p.5 stay bounded; a second tap copies nothing', async () => {
    const now = t.ctx.clock.now();
    const anchor = JSON.stringify(anchorOf(L, 5));
    t.ctx.db.tx(() => {
      for (let i = 0; i < 5000; i++) {
        const id = `DENSE${String(i).padStart(5, '0')}`;
        const x = (i % 70) / 100;
        const y = Math.floor(i / 70) / 80;
        t.ctx.db.run(
          `INSERT INTO annotation (id, kind, tool, anchor_json, data_json, layer, z, locked, anchor_status, rev, created_at, updated_at) VALUES (?, 'ink', 'pen', ?, ?, 'ink', ?, 0, 'ok', 1, ?, ?)`,
          [id, anchor, JSON.stringify(ink(x, y)), i, now, now],
        );
        t.ctx.db.run(`INSERT INTO annotation_target (annotation_id, target_type, target_id) VALUES (?, 'source_page', ?)`, [id, L.v1Pages[4]]);
      }
    });
    const t0 = performance.now();
    const pv = (await t.app.inject({ method: 'GET', url: `/api/annotations/reanchor-copy?source_id=${L.sourceId}`, headers: h })).json() as ReanchorCopyPreview;
    const previewMs = performance.now() - t0;
    expect(pv).toMatchObject({ state: 'ready', total: 5000, copy: 5000, needs_review: 0 });
    const t1 = performance.now();
    const res = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy', headers: h, payload: { source_id: L.sourceId, from_version_id: L.v1, to_version_id: L.v2 } });
    const runMs = performance.now() - t1;
    expect((res.json() as ReanchorCopyRunResponse).report).toMatchObject({ copied: 5000, total: 5000 });
    const t2 = performance.now();
    const again = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy', headers: h, payload: { source_id: L.sourceId, from_version_id: L.v1, to_version_id: L.v2 } });
    const noopMs = performance.now() - t2;
    expect((again.json() as ReanchorCopyRunResponse).report).toMatchObject({ id: null, copied: 0, already_moved: 5000 });
    const t3 = performance.now();
    const u = await t.app.inject({ method: 'POST', url: '/api/annotations/reanchor-copy/undo', headers: h, payload: { run_id: (res.json() as ReanchorCopyRunResponse).report.id } });
    const undoMs = performance.now() - t3;
    expect((u.json() as { report: ReanchorCopyReport }).report.undo).toEqual({ tombstoned: 5000, kept_edited: 0 });
    console.log(`[reanchor-copy perf] 5000 strokes: preview ${previewMs.toFixed(0)} ms, tap ${runMs.toFixed(0)} ms, second tap ${noopMs.toFixed(0)} ms, undo ${undoMs.toFixed(0)} ms`);
    // generous bounds for a shared CI machine (the measured numbers are in docs/PERFORMANCE.md)
    expect(previewMs).toBeLessThan(5000);
    expect(runMs).toBeLessThan(15000);
  }, 120_000);
});
